import math


def locate_plateaus(matrix, cutoff):
    def valid_number(value):
        return (
            not isinstance(value, bool)
            and isinstance(value, (int, float))
            and math.isfinite(value)
        )

    if not valid_number(cutoff):
        raise ValueError("cutoff must be finite and numeric")
    if not isinstance(matrix, list):
        raise ValueError("matrix must be a list")
    if not matrix:
        return []
    if any(not isinstance(row, list) or not row for row in matrix):
        raise ValueError("rows must be non-empty lists")

    width = len(matrix[0])
    if any(len(row) != width for row in matrix):
        raise ValueError("matrix must be rectangular")
    if any(not valid_number(value) for row in matrix for value in row):
        raise ValueError("cells must be finite numbers")

    result = []
    height = len(matrix)
    for row in range(height):
        for column in range(width):
            value = matrix[row][column]
            neighbors = []
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = row + dr, column + dc
                if 0 <= nr < height and 0 <= nc < width:
                    neighbors.append(matrix[nr][nc])
            if value > cutoff and all(value > neighbor for neighbor in neighbors):
                result.append({"row": row, "column": column, "value": value})

    result.sort(key=lambda item: (-item["value"], item["row"], item["column"]))
    return result

